 const clothingHero=store.heroImage||products.find(p=>p.active&&p.image)?.image||products[0]?.image||'';
 const collectionVideo=isVideoMedia(store.collectionBackgroundImage);
 const style={"--accent":store.accent,"--store-bg":store.backgroundColor,"--store-image":store.backgroundImage?`url(${store.backgroundImage})`:'none',"--collection-bg":store.collectionBackgroundColor,"--collection-image":store.collectionBackgroundImage&&!collectionVideo?`url(${store.collectionBackgroundImage})`:'none',"--collection-overlay":store.collectionBackgroundImage?store.collectionOverlayStrength:0,"--surface-image":store.surfaceBackgroundImage?`url(${store.surfaceBackgroundImage})`:'none',"--heading-font":store.headingFont,"--hero-font":store.heroFont,"--store-name-font":store.storeNameFont,"--hero-eyebrow-font":store.heroEyebrowFont,"--hero-highlight-font":store.heroHighlightFont,"--hero-description-font":store.heroDescriptionFont,"--hero-cta-font":store.heroCtaFont,"--product-font":store.productFont,"--price-font":store.priceFont,"--button-font":store.buttonFont,"--button":store.buttonColor,"--button-text":contrastText(store.buttonColor),"--secondary":store.secondaryColor,"--secondary-text":contrastText(store.secondaryColor),"--hero-button":store.heroButtonColor,"--hero-button-text":contrastText(store.heroButtonColor),"--store-text":store.textColor,"--surface":store.surfaceColor,"--overlay":store.backgroundImage?store.overlayStrength:0,fontFamily:`${store.fontFamily}, Arial, sans-serif`,color:store.textColor} as React.CSSProperties;
 if(adminLoading)return <main className="admin-gate"><div className="admin-gate-spinner"></div><b>ABRIENDO ADMINISTRADOR</b><span>Preparando tu catálogo de {templates[template].label.toLowerCase()}…</span></main>;
 if(adminError)return <main className="admin-gate"><b>NO SE PUDO ABRIR</b><span>{adminError}</span><button onClick={()=>location.reload()}>Volver a intentar</button><a href={catalogPath(template)}>Ir al catálogo</a></main>;
 if(startAdmin)return <AdminV2 template={activeTemplate} products={products} store={store} setStore={setStore} section={section} setSection={setSection} editing={editing} setEditing={setEditing} saveProduct={saveProduct} removeProduct={removeProduct} saveSettings={saveSettings} close={()=>location.href=catalogPath(activeTemplate)} notice={notice}/>;
 if(catalogLoading)return <main className="catalog-loading-screen"><span></span><b>Cargando catálogo…</b></main>;
