 const removable=(index:number)=>{const offset=index*4,r=pixels[offset],g=pixels[offset+1],b=pixels[offset+2],distance=Math.hypot(r-bgR,g-bgG,b-bgB);return pixels[offset+3]<12||(distance<52&&r+g+b>610)};
