 const canvas=document.createElement('canvas');canvas.width=500;canvas.height=500;const ctx=canvas.getContext('2d');if(!ctx){bitmap.close();throw new Error('invalid_image')}
 ctx.fillStyle='#f2f2f2';ctx.fillRect(0,0,500,500);const scale=Math.min(470/bitmap.width,470/bitmap.height),width=bitmap.width*scale,height=bitmap.height*scale;ctx.drawImage(bitmap,(500-width)/2,(500-height)/2,width,height);bitmap.close();
