async function drawSkyFlyer(ctx:CanvasRenderingContext2D,images:string[],d:{headline:string;subject:string;price:number;description:string;store:Store}){
 const sky=ctx.createLinearGradient(0,0,0,1350);sky.addColorStop(0,'#19385e');sky.addColorStop(.62,'#395b7b');sky.addColorStop(1,'#d8c3a0');ctx.fillStyle=sky;ctx.fillRect(0,0,1080,1350);for(let i=0;i<14;i++){ctx.fillStyle=`rgba(255,238,207,${.12+(i%4)*.04})`;ctx.beginPath();ctx.arc((i*137)%1180,770+(i%5)*100,110+(i%3)*45,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='900 30px Arial';ctx.fillText(d.store.name.toUpperCase(),540,60);ctx.font='900 64px Arial';drawCenteredFlyerText(ctx,d.headline.toUpperCase(),540,130,930,68);await drawFlyerImage(ctx,images[0],130,220,820,470);await drawFlyerImage(ctx,images[1],130,770,820,470);ctx.fillStyle='#fff';roundedRect(ctx,310,700,460,52,26);ctx.fill();ctx.fillStyle='#17334f';ctx.font='900 22px Arial';ctx.fillText(`${d.subject.toUpperCase()} · S/ ${d.price}`,540,734);ctx.textAlign='left';
}
async function drawNeonFlyer(ctx:CanvasRenderingContext2D,images:string[],d:{headline:string;subject:string;price:number;description:string;store:Store}){
 const g=ctx.createRadialGradient(780,430,40,540,600,880);g.addColorStop(0,'#8e194d');g.addColorStop(.5,'#2c0a25');g.addColorStop(1,'#07070b');ctx.fillStyle=g;ctx.fillRect(0,0,1080,1350);ctx.globalAlpha=.18;ctx.fillStyle='#ff236d';ctx.font='900 220px Arial';ctx.fillText('GHOST',20,260);ctx.globalAlpha=1;ctx.fillStyle='#fff';ctx.font='900 28px Arial';ctx.fillText(d.store.name.toUpperCase(),55,62);await drawFlyerImage(ctx,images[0],105,175,870,850);ctx.fillStyle='#ff3c78';ctx.textAlign='center';ctx.font='900 38px Arial';ctx.fillText(d.headline.toUpperCase(),540,1080);ctx.fillStyle='#fff';ctx.font='700 19px Arial';ctx.fillText(`${d.subject.toUpperCase()} · S/ ${d.price}`,540,1120);drawBenefitRow(ctx,['TELA PREMIUM','DISEÑO EXCLUSIVO','DROP LIMITADO'],1190,'#ff3c78');ctx.textAlign='left';
}
async function drawEditorialFlyer(ctx:CanvasRenderingContext2D,images:string[],d:{headline:string;subject:string;price:number;description:string;store:Store}){
 ctx.fillStyle='#eee9df';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#181818';ctx.textAlign='center';ctx.font='500 18px Georgia';ctx.fillText('CALIDAD · ESTILO · IDENTIDAD',540,48);ctx.font='700 64px Georgia';ctx.fillText(d.store.name.toUpperCase(),540,120);ctx.fillStyle='#8d2529';ctx.font='700 21px Arial';ctx.fillText(d.headline.toUpperCase(),540,162);await Promise.all([drawFlyerImage(ctx,images[0],85,255,445,770),drawFlyerImage(ctx,images[1],550,255,445,770)]);ctx.fillStyle='#181818';ctx.font='900 30px Arial';ctx.fillText(d.subject.toUpperCase(),540,1082);drawBenefitRow(ctx,['PREMIUM','DURABILIDAD','COMODIDAD','DISEÑO ÚNICO'],1140,'#722126');ctx.fillStyle='#722126';ctx.font='900 42px Arial';ctx.fillText(`S/ ${d.price}`,540,1295);ctx.textAlign='left';
}
async function drawPremiumFlyer(ctx:CanvasRenderingContext2D,images:string[],d:{headline:string;subject:string;price:number;description:string;store:Store}){
 ctx.fillStyle='#faf9f7';ctx.fillRect(0,0,1080,1350);ctx.fillStyle=d.store.accent;ctx.fillRect(48,48,105,72);ctx.fillStyle='#fff';ctx.font='900 20px Arial';ctx.fillText(d.store.name.slice(0,9).toUpperCase(),58,88);ctx.fillStyle='#111118';ctx.font='900 82px Arial';drawFlyerText(ctx,d.headline.toUpperCase(),48,210,440,86);ctx.fillStyle=d.store.accent;ctx.font='800 34px Arial';ctx.fillText(d.subject.toUpperCase(),48,415);await drawFlyerImage(ctx,images[0],330,170,710,900);const items=['100% ALGODÓN','CORTE RELAJADO','TALLAS DISPONIBLES','COSTURA REFORZADA'];items.forEach((item,i)=>{ctx.strokeStyle='#d9d6d2';ctx.lineWidth=2;roundedRect(ctx,48,500+i*140,260,108,18);ctx.stroke();ctx.fillStyle=d.store.accent;ctx.beginPath();ctx.arc(82,554+i*140,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#16161b';ctx.font='800 19px Arial';drawFlyerText(ctx,item,115,548+i*140,175,24)});ctx.fillStyle=d.store.buttonColor;roundedRect(ctx,48,1195,360,82,18);ctx.fill();ctx.fillStyle=contrastText(d.store.buttonColor);ctx.font='900 25px Arial';ctx.fillText('PIDE AHORA  →',92,1247);ctx.fillStyle='#111118';ctx.textAlign='right';ctx.font='900 42px Arial';ctx.fillText(`S/ ${d.price}`,1018,1248);ctx.textAlign='left';
}
function drawCenteredFlyerText(ctx:CanvasRenderingContext2D,text:string,x:number,y:number,maxWidth:number,lineHeight:number){const previous=ctx.textAlign;ctx.textAlign='center';const words=text.split(' ');let line='',lineY=y;for(const word of words){const test=`${line}${word} `;if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line.trim(),x,lineY);line=word+' ';lineY+=lineHeight}else line=test}if(line)ctx.fillText(line.trim(),x,lineY);ctx.textAlign=previous}
function drawBenefitRow(ctx:CanvasRenderingContext2D,items:string[],y:number,color:string){const width=900/items.length;ctx.textAlign='center';items.forEach((item,index)=>{const x=90+width*index+width/2;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,19,0,Math.PI*2);ctx.stroke();ctx.fillStyle=color;ctx.font='800 16px Arial';drawCenteredFlyerText(ctx,item,x,y+55,width-20,19)});ctx.textAlign='left'}
async function drawFlyerImage(ctx:CanvasRenderingContext2D,url:string,x:number,y:number,w:number,h:number){const response=await fetch(url);if(!response.ok)throw new Error('image');const bitmap=await createImageBitmap(await response.blob());const scale=Math.max(w/bitmap.width,h/bitmap.height),sw=w/scale,sh=h/scale,sx=(bitmap.width-sw)/2,sy=(bitmap.height-sh)/2;ctx.save();roundedRect(ctx,x,y,w,h,24);ctx.clip();ctx.drawImage(bitmap,sx,sy,sw,sh,x,y,w,h);ctx.restore();bitmap.close()}
function roundedRect(ctx:CanvasRenderingContext2D,x:number,y:number,w:number,h:number,r:number){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawFlyerText(ctx:CanvasRenderingContext2D,text:string,x:number,y:number,maxWidth:number,lineHeight:number){const words=text.split(' ');let line='',lineY=y;for(const word of words){const test=`${line}${word} `;if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line.trim(),x,lineY);line=word+' ';lineY+=lineHeight}else line=test}if(line)ctx.fillText(line.trim(),x,lineY)}

function ProductEditor({p,close,save}:{p:Product;close:()=>void;save:(p:Product)=>void}){
 const[d,setD]=useState({...p,options:p.options||[],whatsappMessage:p.whatsappMessage||''});
 const[uploading,setUploading]=useState(false);
 const[uploadError,setUploadError]=useState('');
 const f=(k:keyof Product,v:string|number|boolean|OptionGroup[])=>setD(x=>({...x,[k]:v}));
 const updateGroupName=(i:number,value:string)=>f('options',(d.options||[]).map((g,n)=>n===i?{...g,name:value}:g));
 const updateGroupValues=(i:number,values:string[])=>f('options',(d.options||[]).map((g,n)=>n===i?{...g,values}:g));
 const addGroup=(name:string)=>f('options',[...(d.options||[]),{name,values:[]}]);
 const removeGroup=(i:number)=>f('options',(d.options||[]).filter((_,n)=>n!==i));
 async function uploadImage(file?:File){if(!file)return;setUploading(true);setUploadError('');const form=new FormData();form.append('file',file);const r=await fetch('/api/upload',{method:'POST',body:form});if(r.ok){const result=await r.json();f('image',result.url)}else setUploadError('No se pudo cargar. Usa JPG, PNG o WebP de hasta 5 MB.');setUploading(false)}
 return <div className="modal-bg"><form className="product-editor" onSubmit={e=>{e.preventDefault();save(d)}}><div className="editor-head"><div><small>{d.id?'EDITAR PRODUCTO':'NUEVO PRODUCTO'}</small><h2>{d.name||'Sin nombre'}</h2></div><button type="button" onClick={close}>×</button></div><label>Nombre<input required value={d.name} onChange={e=>f('name',e.target.value)}/></label><label>Marca o categoría<input value={d.category} onChange={e=>f('category',e.target.value)}/></label><label>Descripción<input value={d.description} onChange={e=>f('description',e.target.value)}/></label><div className="two"><label>Precio<input type="number" value={d.price} onChange={e=>f('price',Number(e.target.value))}/></label><label>Precio anterior<input type="number" value={d.oldPrice} onChange={e=>f('oldPrice',Number(e.target.value))}/></label></div><section className="product-image-uploader"><div>{d.image?<img src={d.image} alt="Vista previa del producto"/>:<span>Sin imagen</span>}</div><label>Foto principal del modelo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>uploadImage(e.target.files?.[0])}/><small>{uploading?'Subiendo imagen...':'JPG, PNG o WebP · máximo 5 MB'}</small></label></section>{uploadError&&<p className="upload-error">{uploadError}</p>}<label>O pegar URL de imagen<input required value={d.image} onChange={e=>f('image',e.target.value)} placeholder="https://..."/></label><section className="options-editor"><div><b>Galería, tallas y opciones</b><span className="option-group-actions"><button type="button" onClick={()=>addGroup('Color')}>+ Galería de fotos</button><button type="button" onClick={()=>addGroup('Talla')}>+ Talla</button><button type="button" onClick={()=>addGroup('Nueva opción')}>+ Otra opción</button></span></div><p>Sube otras fotos del mismo modelo para crear un carrusel. No se mostrarán nombres ni puntos de color al cliente.</p>{(d.options||[]).map((group,i)=><OptionGroupEditor key={i} group={group} updateName={value=>updateGroupName(i,value)} updateValues={values=>updateGroupValues(i,values)} remove={()=>removeGroup(i)}/>)}</section><label>Mensaje de WhatsApp para este artículo<textarea rows={5} value={d.whatsappMessage} onChange={e=>f('whatsappMessage',e.target.value)} placeholder={'Hola, quiero pedir {producto}.\n{opciones}\nPrecio: S/ {precio}'}/><small className="field-help">Puedes usar: {'{producto}'}, {'{precio}'} y {'{opciones}'}. La galería no agrega nombres de color al mensaje.</small></label><label className="checkbox"><input type="checkbox" checked={d.active} onChange={e=>f('active',e.target.checked)}/> Producto visible</label><div className="editor-actions"><button type="button" onClick={close}>Cancelar</button><button disabled={uploading}>Guardar producto</button></div></form></div>
}

function OptionGroupEditor({group,updateName,updateValues,remove}:{group:OptionGroup;updateName:(value:string)=>void;updateValues:(values:string[])=>void;remove:()=>void}){
 const[draft,setDraft]=useState('');
 const[uploadingIndex,setUploadingIndex]=useState<number|null>(null);
 const[photoError,setPhotoError]=useState('');
 const isColor=group.name.toLowerCase().includes('color');
 const addValue=()=>{const label=draft.trim();if(!label)return;updateValues([...group.values,label]);setDraft('')};
 const changeValue=(index:number,label:string,color?:string,image?:string)=>updateValues(group.values.map((value,i)=>{if(i!==index)return value;const parsed=parseOptionValue(value);return isColor?colorValue(label,color||colorSwatch(value),image===undefined?parsed.image:image):label}));
 const removeValue=(index:number)=>updateValues(group.values.filter((_,i)=>i!==index));
 const valueName=group.name.toLowerCase().includes('talla')?'talla':isColor?'color':'opción';
 async function uploadColorPhoto(index:number,file?:File){if(!file)return;setUploadingIndex(index);setPhotoError('');const form=new FormData();form.append('file',file);const response=await fetch('/api/upload',{method:'POST',body:form});if(response.ok){const result=await response.json();const parsed=parseOptionValue(group.values[index]);changeValue(index,parsed.label,parsed.color||colorSwatch(group.values[index]),String(result.url))}else setPhotoError('No se pudo subir la foto de color.');setUploadingIndex(null)}
 if(isColor){
  const addPhotoSlot=()=>updateValues([...group.values,colorValue(`Foto ${group.values.length+2}`,'#8d96a5')]);
  return <article className="option-editor-card gallery-editor"><div className="option-editor-head"><div><b>Fotos adicionales del modelo</b><small>Se mostrarán como carrusel en el administrador y en el catálogo.</small></div><button type="button" className="remove-option-group" onClick={remove}>Quitar galería</button></div><div className="variant-photo-grid">{group.values.map((value,index)=>{const parsed=parseOptionValue(value);return <div className="variant-photo-card" key={index}>{parsed.image?<img src={parsed.image} alt={`Foto adicional ${index+1}`}/>:<span>Foto {index+2}</span>}<label>{uploadingIndex===index?'Subiendo…':parsed.image?'Cambiar foto':'Subir foto'}<input type="file" accept="image/png,image/jpeg,image/webp" disabled={uploadingIndex!==null} onChange={e=>uploadColorPhoto(index,e.target.files?.[0])}/></label><button type="button" onClick={()=>removeValue(index)} aria-label={`Eliminar foto ${index+2}`}>×</button></div>})}</div>{photoError&&<p className="upload-error">{photoError}</p>}<button type="button" className="add-gallery-photo" onClick={addPhotoSlot}>+ Agregar otra foto</button></article>
 }
 return <article className="option-editor-card"><div className="option-editor-head"><label>Nombre del grupo<input value={group.name} onChange={e=>updateName(e.target.value)}/></label><button type="button" className="remove-option-group" onClick={remove}>Quitar grupo</button></div><div className="option-value-list">{group.values.map((value,index)=>{const parsed=parseOptionValue(value);return <div className="option-value-row" key={index}><input value={parsed.label} aria-label={`Nombre de ${valueName}`} onChange={e=>changeValue(index,e.target.value)}/><button type="button" onClick={()=>removeValue(index)} aria-label={`Eliminar ${parsed.label}`}>×</button></div>})}</div><div className="option-value-add"><input value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();addValue()}}} placeholder={`Nueva ${valueName}`}/><button type="button" onClick={addValue}>+ Agregar {valueName}</button></div></article>
}






